<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Student');$u=current_user();$q=db()->prepare('SELECT u.name,u.email,u.profile_photo,s.* FROM users u JOIN students s ON s.user_id=u.id WHERE u.id=?');$q->execute([$u['id']]);$s=$q->fetch();page_top('My Digital Identity');?><div class="row g-4"><div class="col-lg-4"><div class="card p-4 text-center"><div class="avatar-xl mx-auto mb-3"><?=e(strtoupper(substr($s['name'],0,1)))?></div><h4><?=e($s['name'])?></h4><div class="text-muted"><?=e($s['enrollment_no'])?></div><span class="badge bg-success mt-2">Digital ID Active</span></div></div><div class="col-lg-8"><div class="card p-4"><div class="row g-3"><?php foreach(['email','mobile','dob','gender','address','parent_name','parent_mobile','admission_no','status'] as $f):?><div class="col-md-6"><label class="form-label text-muted"><?=e(ucwords(str_replace('_',' ',$f)))?></label><div class="form-control bg-light"><?=e($s[$f]??'')?></div></div><?php endforeach;?></div><p class="small text-muted mt-3 mb-0">Academic identity fields are controlled by authorized college staff.</p></div></div></div><?php page_bottom();
